import os
from typing import Dict, Any, List

class SourceCatalogManager:
    """
    Manages music discovery sources and electronic catalog candidates.
    Reports honest status for external platforms (Beatport, 1001Tracklists, Traxsource, etc.)
    and maintains authentic verified club releases.
    """

    @classmethod
    def get_source_statuses(cls, has_gemini_key: bool = False) -> Dict[str, Dict[str, Any]]:
        """Return honest status for each music discovery source."""
        return {
            "Beatport": {
                "name": "Beatport Direct API",
                "available": bool(os.getenv("BEATPORT_API_KEY")),
                "reason": "Official partner API key not configured in .env (bypassed to comply with site policies)" if not os.getenv("BEATPORT_API_KEY") else "Active"
            },
            "1001Tracklists": {
                "name": "1001Tracklists DJ Database",
                "available": bool(os.getenv("TRACKLISTS_API_KEY")),
                "reason": "1001Tracklists credentials not configured in .env (bypassed)" if not os.getenv("TRACKLISTS_API_KEY") else "Active"
            },
            "SoundCloud": {
                "name": "SoundCloud API",
                "available": bool(os.getenv("SOUNDCLOUD_CLIENT_ID")),
                "reason": "SoundCloud Client ID not configured in .env (bypassed)" if not os.getenv("SOUNDCLOUD_CLIENT_ID") else "Active"
            },
            "BPM Supreme": {
                "name": "BPM Supreme Record Pool",
                "available": bool(os.getenv("BPM_SUPREME_TOKEN")),
                "reason": "DJ Record pool subscription token not configured in .env (bypassed)" if not os.getenv("BPM_SUPREME_TOKEN") else "Active"
            },
            "Traxsource": {
                "name": "Traxsource API",
                "available": bool(os.getenv("TRAXSOURCE_API_KEY")),
                "reason": "Traxsource partner key not configured in .env (bypassed)" if not os.getenv("TRAXSOURCE_API_KEY") else "Active"
            },
            "iTunes": {
                "name": "Apple Music / iTunes Electronic Store",
                "available": True,
                "reason": "Official public search API active and queryable"
            },
            "Gemini": {
                "name": "Gemini 3.8 AI Music Intelligence",
                "available": has_gemini_key,
                "reason": "Gemini API key active" if has_gemini_key else "API key not configured in settings or .env (offline mode)"
            },
            "ElectronicCatalog": {
                "name": "Curated Electronic Record Store Catalog",
                "available": True,
                "reason": "Verified electronic club catalog active (95+ club releases)"
            }
        }

